-- HQ.ai | Semantic escalation classifier (safety gate v2).
-- Anchors from the Section 6 boundary map. score = max cos to escalate - max cos to safe.
-- predict_escalation_v2 = keyword rule OR score>=threshold. Run AFTER 08_vector_baseline.sql.

create extension if not exists vector;
drop table if exists public.hr_escalation_anchor cascade;
create table public.hr_escalation_anchor(id serial primary key, kind text check(kind in ('escalate','safe')), txt text, embedding vector(384));

create or replace function public.escalation_semantic_score(qvec vector(384))
returns numeric language sql stable as $$
  select (select max(1-(a.embedding <=> qvec)) from public.hr_escalation_anchor a where a.kind='escalate')
       - (select max(1-(a.embedding <=> qvec)) from public.hr_escalation_anchor a where a.kind='safe');
$$;

create or replace function public.predict_escalation_v2(qtext text, qvec vector(384), threshold numeric default 0.108)
returns boolean language sql stable as $$
  select public.predict_escalation(qtext) or public.escalation_semantic_score(qvec) >= threshold;
$$;

create or replace function public.run_escalation_v2(p_label text, p_threshold numeric default 0.108) returns uuid language plpgsql as $$
declare v uuid; begin
  select v,g.id, public.predict_escalation_v2(g.question_text, ge.embedding, p_threshold), true, 0
  from public.hr_eval_gold g join public.hr_gold_embedding ge on ge.ext_id=g.ext_id;
  return v; end; $$;
